// Mascot sound effects: randomly picks on each sip between 4 iconic video game drinking sounds:
// 1. Roblox "Nom nom nom" (roblox_nom) - 0.76s
// 2. Minecraft Potion Drinking (minecraft_drink) - 1.73s
// 3. Roblox Bloxy Cola Drinking Sound Effect (roblox_drink) - 2.15s (slurps, gulp + iconic "ahhh!")
// 4. Fortnite Shield Potion Drinking Sound Effect (fortnite_shield) - 6.02s (uncork, chugs + ascending shield chime!)
// Opt-in only (muted until the user clicks the sound pill).

const CLIP_B64 = {
  roblox_nom: "",
  minecraft_drink: "",
  roblox_drink: "",
  fortnite_shield: "",
};

const DRINK_SOUND_KEYS = ["roblox_nom", "minecraft_drink", "roblox_drink", "fortnite_shield"];

export class SipSound {
  constructor() {
    this.ctx = null;
    this.buffers = {};
    this.on = false;
    this.unlocked = false;
    this.activeSources = [];
    this._bag = [];
    this.lastChoice = null;
  }

  unlock() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      this.ctx = new AudioCtx();
    }
    if (this.ctx.state === "suspended") this.ctx.resume();
    if (!this.unlocked) {
      this.unlocked = true;
      this._decodeClips();
    }
  }

  _decodeClips() {
    if (!this.ctx) return;
    for (const [key, b64] of Object.entries(CLIP_B64)) {
      try {
        const bin = atob(b64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        this.ctx.decodeAudioData(bytes.buffer.slice(0), (buf) => {
          this.buffers[key] = buf;
        }, (err) => console.warn("Failed to decode sound clip", key, err));
      } catch (e) {
        console.warn("Sound base64 parse failed", key, e);
      }
    }
  }

  toggle() {
    this.on = !this.on;
    if (this.on) this.unlock();
    else this.stopActive();
    return this.on;
  }

  stopActive() {
    for (const s of this.activeSources) {
      try { s.stop(); } catch (e) {}
    }
    this.activeSources.length = 0;
  }

  _nextRandomKey() {
    // Shuffled bag with random draws so every iconic sound gets heard without long dry streaks
    if (this._bag.length === 0) {
      this._bag = [...DRINK_SOUND_KEYS];
      for (let i = this._bag.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [this._bag[i], this._bag[j]] = [this._bag[j], this._bag[i]];
      }
      if (this.lastChoice && this._bag[this._bag.length - 1] === this.lastChoice) {
        [this._bag[0], this._bag[this._bag.length - 1]] = [this._bag[this._bag.length - 1], this._bag[0]];
      }
    }
    return this._bag.pop();
  }

  pickNextChoice() {
    return this._nextRandomKey();
  }

  playDrinkClip(forceKind = null) {
    if (!this.on) return null;
    this.unlock();
    if (!this.ctx) return null;
    const choice = forceKind || this._nextRandomKey();
    this.lastChoice = choice;
    const buf = this.buffers[choice];
    if (!buf) {
      // First sip after unmuting: clips are still decoding. Poll briefly and play when ready.
      const retry = (n) => setTimeout(() => {
        if (!this.on) return;
        const b = this.buffers[choice];
        if (b) this._startBuffer(b, choice);
        else if (n > 0) retry(n - 1);
      }, 50);
      retry(30);
      return choice;
    }
    this._startBuffer(buf, choice);
    return choice;
  }

  _startBuffer(buf, choice) {
    this.stopActive();
    const c = this.ctx, t0 = c.currentTime + 0.01;
    const playDur = buf.duration;

    const src = c.createBufferSource();
    src.buffer = buf;
    src.loop = false;

    const g = c.createGain();
    const peak = choice === "roblox_nom" ? 0.65 : 0.60;
    g.gain.setValueAtTime(0.001, t0);
    g.gain.linearRampToValueAtTime(peak, t0 + 0.02);
    g.gain.setValueAtTime(peak, t0 + Math.max(0.05, playDur - 0.05));
    g.gain.linearRampToValueAtTime(0.0008, t0 + playDur);

    src.connect(g).connect(c.destination);
    src.start(t0);
    src.stop(t0 + playDur + 0.04);
    this.activeSources.push(src);
    src.onended = () => {
      const idx = this.activeSources.indexOf(src);
      if (idx >= 0) this.activeSources.splice(idx, 1);
    };
  }

  pop(amp = 0.8) {
    if (!this.on || !this.ctx) return;
    const c = this.ctx, t0 = c.currentTime;
    const o = c.createOscillator(), g = c.createGain();
    o.type = "triangle";
    o.frequency.setValueAtTime(140, t0);
    o.frequency.exponentialRampToValueAtTime(310, t0 + 0.055);
    o.frequency.exponentialRampToValueAtTime(180, t0 + 0.11);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(0.16 * amp, t0 + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.12);
    o.connect(g).connect(c.destination);
    o.start(t0); o.stop(t0 + 0.13);
  }

  sipStart(plan, chosenClip = null) {
    if (!this.on) return;
    this.unlock();
    const clip = chosenClip || this.pickNextChoice();
    this.playDrinkClip(clip);
    return clip;
  }

  event(e, plan) {
    if (!this.on) return;
    if (e.name === "pop") this.pop(plan.kind === "empty" ? 0.45 : 0.70);
  }
}
